function MaidCoffeeComponent:RemoveEventListener()
    if self.onEventEnergyChange then
        Events.RemoveListener(MaidCoffeeConstants.EventNames.SetManageCloudShowState, self.onEventEnergyChange)
        self.onEventEnergyChange = nil
    end

    if self.onRoleChangeEvent then
        Events.RemoveListener(MaidCoffeeConstants.EventNames.MaidCoffeeRoleSelect, self.onRoleChangeEvent)
        self.onRoleChangeEvent = nil
    end

    if self.onFinishEvent then
        Events.RemoveListener(MaidCoffeeConstants.EventNames.MaidCoffeeFinishEvents, self.onFinishEvent)
        self.onFinishEvent = nil
    end
end

function MaidCoffeeComponent:OnSelectRoleChange(type,data,index)
    if type == MaidCoffeeConstants.SelectType.Lounge then
        self:ResetLoungeData(data,index)
    elseif type == MaidCoffeeConstants.SelectType.Manager then
        self:ResetManageData(data)
    elseif type == MaidCoffeeConstants.SelectType.Clerk then
        self:ResetClerkData(data)
    elseif type == MaidCoffeeConstants.SelectType.DeliveryMan then
        self:ResetDeliveryManData(data,index)
    end
end

function MaidCoffeeComponent:ResetLoungeData(selectData,roomId)
    local cardIds = {}
    for index, value in ipairs(selectData) do
        table.insert(cardIds, value.id)
    end
    local update = table.serialize({[tostring(roomId)] = table.concat(cardIds, ",")})
    local interface = Interfaces.MaidCoffeeLoungeUpdate
    GameUtils.Request(interface, {update = update}, function(req, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeLoungeRoleChange)
    end)
end

function MaidCoffeeComponent:ResetDeliveryManData(data,teamId)
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)

    local t = {}
    for i, v in pairs(data) do
        if checkNumber(v.id) > 0 then
            ---@type CardComponent
            local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
            cardComponent:UpdateCardDojo(v.id, {cafeStatus = MaidCoffeeConstants.CafeStatus.Non})
            table.insert(t, v.id)
        end
    end

    maidCoffeePlayerComponent:UpdateRemoteTeamByTeamId(teamId, t, function()
        Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeDeliveryManChange,data)
    end)
end

function MaidCoffeeComponent:ResetClerkData(selectData)
    local data = {}
    local isChange = false
    for i, v in pairs(selectData) do
        local pos = MaidCoffeeConstants.SelectType.Clerk * 100 + i
        local id = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Clerk ,i)
        if v.id ~= id then
            isChange = true
        end
        data[tostring(pos)] = v.id
    end

    if isChange then
        GameUtils.Request(Interfaces.MaidCoffeeSetStaff, {staffs = table.serialize(data)}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                for i, v in pairs(data) do
                    self:UpdateStaffInfo(i,tonumber(v))
                end
                Events.Broadcast("MaidCoffee_PersonChange",{type = MaidCoffeeConstants.SelectType.Clerk,data = data })
            end
        end)
    end
end

function MaidCoffeeComponent:ResetManageData(selectData)
    local data = {}
    local isChange = false
    for i, v in pairs(selectData) do
        local pos = MaidCoffeeConstants.SelectType.Manager * 100 + i
        local id = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,i)
        if v.id ~= id then
