function MaidCoffeeComponent:GetMenuFoodPrice(tableIndex,slotIndex,recipeId)
    local isDouble  = self:IsMenuDouble(tableIndex,slotIndex,recipeId)
    local vo = MaidCoffeeUtils.GetMaidCoffeeMenuMakeVo(recipeId)
    local doubleRate = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(2).num)
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local recipeInfo = maidCoffeePlayerComponent:GetRecipeDoJoById(recipeId)
    local rating = recipeInfo.rating
    local price = 0
    if vo then
        price = vo:GetPrice(rating)
        if isDouble then
            price = price * doubleRate
        end
    end
    return price
end

