    return rate
end

---也就是UP菜>售价高>品质
---@param index integer @ 表示当前是那个套餐 对应页签123
function MaidCoffeeComponent:GetHighPriceFoodByIndex(index)
    local data = {}
    local sortData = {}
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local needFood = self:GetNeedPutOnFoodCount(index)
    for i = 1, needFood do
        local vos =  MaidCoffeeMgr:GetInstance():GetMenuNodeVos(index , i)
        sortData[i] = {}
        for k, v in pairs(clone(vos)) do
            local serverInfo = maidCoffeePlayerComponent:GetRecipeDoJoById(v.refId)
            if serverInfo then
                local isDouble = component:IsMenuDouble(index,i,v.refId)
                local data = {}
                data.IsDouble = isDouble and 1 or 0
                data.Rating = serverInfo.rating
                data.SellPrice = v:GetPrice(serverInfo.rating)
                data.Id = v.refId
                data.Vo = v
                table.insert(sortData[i],data)
            end
        end
        table.sort(sortData[i],function(a,b)
            if a.IsDouble == b.IsDouble then
                if a.SellPrice == b.SellPrice then
                    if a.Rating == b.Rating then
                        return a.Id > b.Id
                    else
                        return a.Rating > b.Rating
                    end
                else
                    return a.SellPrice > b.SellPrice
                end
            else
                return a.IsDouble > b.IsDouble
            end
        end)
        if #sortData[i] > 0 then
            data[i] = sortData[i][1].Vo
        end
    end

    return data
end

function MaidCoffeeComponent:CalculationMenuPrice(tabIndex,data)
    local sellPrices = {}
    local costs = {}
    local gets = {}
    local sellNum = 1
    local doubleRate = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(2).num)
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    for k,v in pairs(data) do
        local serverInfo =maidCoffeePlayerComponent:GetRecipeDoJoById(v.refId)
        local rating = serverInfo.rating or k
        local isDouble = self:IsMenuDouble(tabIndex,k,v.refId )
        sellPrices[k] = v:GetPrice(rating)
        if isDouble then
            sellPrices[k] = sellPrices[k] *  doubleRate
        end
        costs[k] = v.cost
        gets[k] = sellPrices[k] - v.cost
    end

    local sellSingle,costSingle, getSingle = self:CalculationPrice(sellPrices,costs,gets,1)
    local goodsId = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(7).num
    local haveNum = GoodsUtils.GetThingNo(goodsId)
    ---获取一下当前套餐最大可售卖数量
    local volume = self:GetIsLockedAndVolume(tabIndex)
    if costSingle * volume <= haveNum then
        sellNum = volume
    else
        sellNum = math.floor(haveNum/costSingle)
    end
    return sellSingle,costSingle,getSingle,sellNum
end

