function MaidCoffeeComponent:GetMaxCountByType(type)
    local maxCount = 1
    if type == MaidCoffeeConstants.SelectType.Manager then
        maxCount = 1
    elseif type == MaidCoffeeConstants.SelectType.Clerk then
        maxCount = 0
        for i = 1, 3 do
            local isLocked,_ = MaidCoffeeMgr:GetInstance():GetIsLocked(MaidCoffeeConstants.SelectType.Clerk,i)
            if not isLocked then
                maxCount = maxCount + 1
            end
        end
    elseif type == MaidCoffeeConstants.SelectType.DeliveryMan then
        maxCount = 5
    elseif type == MaidCoffeeConstants.SelectType.Cat then
        maxCount = 0
        for i = 1, MaidCoffeeConstants.MaidCoffeeCatCount do
            local isLocked,_ = MaidCoffeeMgr:GetInstance():GetIsLocked(MaidCoffeeConstants.SelectType.Cat,i)
            if not isLocked then
                maxCount = maxCount + 1
            end
        end
    elseif type == MaidCoffeeConstants.SelectType.Lounge then
        return checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(MaidCoffeeConstants.ParamsIds.LoungeCapacity).num)
    end
    return maxCount
end

