function MaidCoffeeComponent:CalculationPrice(sellPrices,costPrices,gets,sellNum)
    local sellAll = 0
    local costAll = 0
    local getAll = 0

    for i, v in pairs(sellPrices) do
        sellAll = sellAll + v * sellNum
    end

    for i, v in pairs(costPrices) do
        costAll = costAll + v * sellNum
    end

    for i, v in pairs(gets) do
        getAll = getAll + v * sellNum
    end
    return sellAll,costAll,getAll
end

