---根据index 等级获取当前套装份数上限 是否解锁
function MaidCoffeeComponent:GetIsLockedAndVolume(i)
    local vo = MaidCoffeeUtils.GetMaidCoffeeMenuVo(i)
    local coffeeLevel = self:GetMaidCoffeeLevel()
    ---默认是100
    local volume = vo.volume
    local isUnLocked = GameUtils.IsUnlockedSingle(vo.unlockType, vo.unlockNum)
    if not isUnLocked then
        return volume, true
    end
    local isFind = false
    for i = 1, #vo.grade do
        if coffeeLevel < tonumber(vo.grade[i]) then
            isFind = true
            if i ~= 1 then
                volume = tonumber(vo.addVolume[i - 1])
            end
            break
        end
    end
    ---当没找到 则表示咖啡店等级大于当前配置最大等级
    if not isFind then
        volume = tonumber(vo.addVolume[#vo.grade])
    end
    return volume,false
end
