---判断当前是升星还是升级
function MaidCoffeeComponent:GetCurIsLevelUp()
    local curLevel = self:GetMaidCoffeeLevel()
    local curStarLevel = self:GetMaidCoffeeCattyStarLevel()
    if math.floor(curLevel/5) > curStarLevel then
        return false
    end
    return true
end

function MaidCoffeeComponent:GetIsCanStarUp()
    if not self:GetIsToMaxStar() then
        local curStar = self:GetMaidCoffeeCattyStarLevel()  --初始为0级  要取下一等级的对应等级
        ---这里不用担心越界 因为如果已经达到最大星级 不会进来这里
        local starVo = MaidCoffeeUtils.GetMaidCoffeeStarUpVo(curStar + 1)
        local costs = starVo.costs
        local count = 0
        for i, v in pairs(costs) do
            local costId = v.goodsId
            local costNum = v.goodsNum
            local haveNum = GoodsUtils.GetThingNo(costId)
            if haveNum >= costNum then
                count = count + 1
            end
        end
        return count == #costs
    end
    return false
end

