end

---是否可以升级  -完成所有任务 道具够
function MaidCoffeeComponent:IsCanLevelUp()
    local curLevel = self:GetMaidCoffeeLevel()
    local vos = MaidCoffeeMgr:GetInstance():GetMaidCoffeeLevelUpVosByLevel(curLevel)
    local isCompleteAll = self:IsCompleteAll(vos)
    local itemEnough = GoodsUtils.GetThingNo(vos[1].costId) >= vos[1].costNum
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local cafeExp = maidCoffeePlayerComponent:GetCafeExp()
    local vo = MaidCoffeeUtils.GetMaidCoffeeLevelExpVo(curLevel)
    local isExpEnough = cafeExp >= vo.exp
    return isCompleteAll and itemEnough and isExpEnough
end

function MaidCoffeeComponent:GetManagerBubbleOffset()
    local offset = Vector2(-0.25,1.8)
    local id = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
    if id ~= 0 then
        ---@type CardComponent
        local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        ---@type CardDojo
        local cardDojo = cardComp:GetCardById(id)
        local cardInfoVo = MaidCoffeeUtils.GetCardManagerInfoVo(cardDojo.cardId)
        offset = Vector2(tonumber(cardInfoVo.bubble[1]) + offset.x,tonumber(cardInfoVo.bubble[2]) + offset.y)
    end
    return offset
end

