--region 计算基础金币收益
function MaidCoffeeComponent:GetBaseCoinIncome()
    local baseCoin = 0
    local IsHaveMenuSell = self:IsHaveMenuSell()
    if not IsHaveMenuSell then
        return baseCoin
    end
    for i = 1, MenuCount do
        baseCoin = baseCoin + self:GetSingeMenuSaleIncome(i)
    end
    return baseCoin
end

function MaidCoffeeComponent:GetSingeMenuSaleIncome(index)
    local baseCoin = 0
    local menuInfo = self.maidCoffeeHomeDojo:GetCurIndexMenuInfo(index)
    local rate = self:GetPriceRate()
    if menuInfo and menuInfo:IsSell() then
        for i, v in pairs(menuInfo.saleRecipes) do
            baseCoin = baseCoin + tonumber(v.price) * rate
        end
    end
    return baseCoin
end

function MaidCoffeeComponent:GetPersonAddBaseCoinIncome()
    local addNum = 0
    local IsHaveMenuSell = self:IsHaveMenuSell()
    if not IsHaveMenuSell then
        return addNum
    end
    local id = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    if id ~= 0 then
        local paramsVo = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(3)
        local cardDojo = cardComponent:GetCardById(tonumber(id))
        if checkNumber(cardDojo.cafeEnergy) >= checkNumber(paramsVo.num) then
            local vo = MaidCoffeeUtils.GetCardManagerInfoVo(cardDojo.cardId)
            ---说明是金币加成
            if vo.additionId == 1001 then
                addNum = addNum + vo.additionNum[1]
            end
        end
    end
    local paramsVo = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(4)
    for i = 1, 3 do
        local staffId = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Clerk ,i)
        if staffId ~= 0 then
            local cardDojo = cardComponent:GetCardById(tonumber(staffId))
            if checkNumber(cardDojo.cafeEnergy) >= checkNumber(paramsVo.num) then
                local vo = MaidCoffeeUtils.GetCardManagerInfoVo(cardDojo.cardId)
                ---说明是金币加成
                if vo.additionId == 1001 then
                    addNum = addNum + vo.additionNum[1]
                end
            end
        end
    end
    return addNum
end

function MaidCoffeeComponent:GetMaidCafeMinEarnings()
    local cafeLevel = self:GetMaidCoffeeLevel()
    local vo = MaidCoffeeUtils.GetMaidCoffeeLevelExpVo(cafeLevel)
    local time = vo.time/60
    local addNum = vo.rewardNum/time
    return addNum
end

function MaidCoffeeComponent:GetCatAddBaseCoinIncome()
    local catAddBase = 0
    local IsHaveMenuSell = self:IsHaveMenuSell()
    if not IsHaveMenuSell then
        return catAddBase
    end

    local signConst = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(26).num)
    local maidCoffeeHomeDojo = self:GetMaidCoffeeHomeDoJo()
    local curPower = maidCoffeeHomeDojo:GetCatElectric()
    if curPower < signConst then
        return catAddBase
    end

    local eggComponent     = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    for i = 1, 6 do
        local staffId = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Cat ,i)
        if staffId ~= 0 then
            local catDojo = eggComponent:GetCat(checkNumber(staffId))
            if catDojo then
                local catVo = MaidCoffeeUtils.GetMaidCoffeeCatRollConfigVo(catDojo.catId)
                if not isNull(catVo) and checkNumber(catVo.coffee) == 1001 then
                    catAddBase = catAddBase + tonumber(catVo.coffeeNum[1])
                end
            end
        end
    end
    return catAddBase
end

function MaidCoffeeComponent:GetAllCoinIncome()
    local all = 0
    local base = self:GetBaseCoinIncome()
    --local personAdd = self:GetPersonAddBaseCoinIncome()
    --local catAdd = self:GetCatAddBaseCoinIncome()
    --local cafeLevelAdd = self:GetMaidCafeMinEarnings()
    all = base -- + base * personAdd + base * catAdd + cafeLevelAdd
    return all
end
