---基础收益从技能 2002读取
function MaidCoffeeComponent:GetPersonBasePraisePointProbabilityAndNum()
    local addNum = 0
    local probability = 0
    local IsHaveMenuSell = self:IsHaveMenuSell()
    if not IsHaveMenuSell then
        return addNum,probability
    end

    local id = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    if id ~= 0 then
        local paramsVo = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(3)
        local cardDojo = cardComponent:GetCardById(tonumber(id))
        if checkNumber(cardDojo.cafeEnergy) >= checkNumber(paramsVo.num) then
            local vo = MaidCoffeeUtils.GetCardManagerInfoVo(cardDojo.cardId)
            ---说明是好评点加成
            if vo.additionId == 2002 then
                addNum = addNum + vo.additionNum[2]
                probability = probability + vo.additionNum[1]
            end
        end
    end
    local paramsVo = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(4)
    for i = 1, 3 do
        local staffId = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Clerk ,i)
        if staffId ~= 0 then
            local cardDojo = cardComponent:GetCardById(tonumber(staffId))
            if checkNumber(cardDojo.cafeEnergy) >= checkNumber(paramsVo.num) then
                local vo = MaidCoffeeUtils.GetCardManagerInfoVo(cardDojo.cardId)
                ---说明是金币加成
                if vo.additionId == 2002 then
                    addNum = addNum + vo.additionNum[2]
                    probability = probability + vo.additionNum[1]
                end
            end
        end
    end
    return addNum,probability
end
