        end
    end
    local paramsVo = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(4)
    for i = 1, 3 do
        local staffId = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Clerk ,i)
        if staffId ~= 0 then
            local cardDojo = cardComponent:GetCardById(tonumber(staffId))
            if checkNumber(cardDojo.cafeEnergy) >= checkNumber(paramsVo.num) then
                local vo = MaidCoffeeUtils.GetCardManagerInfoVo(cardDojo.cardId)
                ---说明是金币加成
                if vo.additionId == 2001 then
                    addPercent = addPercent + vo.additionNum[1]
                end
            end
        end
    end
    return addPercent
end
---和技能 5003 有关  套餐推荐收益
function MaidCoffeeComponent:GetPraisePointRecommendPrisePoint()
    local addNum = 0
    local isHaveMenuSell = self:IsHaveMenuSell()
    if isHaveMenuSell then
        for i = 1, MenuCount do
            local menuInfo = self:GetCurIndexMenuInfo(i)
            if menuInfo and menuInfo:IsSell() then
                for i, v in pairs(menuInfo.saleRecipes) do
                    local skill = v.skill
                    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
                    local recipeDojo = maidCoffeePlayerComponent:GetRecipeDoJoById(v.recipeId)
                    if skill == 5003 then
                        local vo = MaidCoffeeUtils.GetMaidCoffeeRecipeSkillVo(skill)
                        local _addNum = string.split(vo.skillNum[recipeDojo.rating],",")
                        addNum = addNum + _addNum[2]
                    end
                end
            end
        end
    end
    return addNum
end

function MaidCoffeeComponent:GetCatAddPrisePointPercent()
    local catAddPercent = 0
    local signConst = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(26).num)
    local maidCoffeeHomeDojo = self:GetMaidCoffeeHomeDoJo()
    local curPower = maidCoffeeHomeDojo:GetCatElectric()
    if curPower < signConst then
       return catAddPercent
    end
    local IsHaveMenuSell = self:IsHaveMenuSell()
    if not IsHaveMenuSell then
        return catAddPercent
    end
    return 0
end

function MaidCoffeeComponent:GetCattySlotAdd()
    local addNum = 0
    for i = 1, MenuCount do
        local _,isLock = self:GetIsLockedAndVolume(i)
        if not isLock then
            local menuInfo = self:GetCurIndexMenuInfo(i)
            if menuInfo and menuInfo:IsSell() then
                local vo = MaidCoffeeUtils.GetMaidCoffeeMenuVo(i)
                for k, v in pairs(menuInfo.saleRecipes) do
                    addNum = addNum + tonumber(vo.restaurantExp[k])
                end
            end
        end
    end
    return addNum
end

function MaidCoffeeComponent:GetAllPrisePoint()
    local all = 0
    local base = self:GetPersonBasePraisePointProbabilityAndNum()
    local personAdd = self:GetPersonAddPrisePointPercent()
    local catAdd = self:GetCatAddPrisePointPercent()
    local cattyAdd = self:GetCattySlotAdd()
    local addition = self:GetPraisePointRecommendPrisePoint()
    all = base + base * personAdd + base * catAdd + cattyAdd + checkNumber(addition)
    return all
end
---5001
function MaidCoffeeComponent:GetMenuAddTipPercent()
    local isHaveMenuSell = self:IsHaveMenuSell()
    local probability = 0
    local addPercent = 0
    if isHaveMenuSell then
        for i = 1, MenuCount do
            local menuInfo = self:GetCurIndexMenuInfo(i)
            if menuInfo and menuInfo:IsSell() then
                for i, v in pairs(menuInfo.saleRecipes) do
                    local skill = v.skill
                    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
                    local recipeDojo = maidCoffeePlayerComponent:GetRecipeDoJoById(v.recipeId)
                    if skill == 5001 then
                        local vo = MaidCoffeeUtils.GetMaidCoffeeRecipeSkillVo(skill)
                        local addNum = string.split(vo.skillNum[recipeDojo.rating],",")
                        if probability == 0 then
                            probability = addNum[1]
                        end
                        addPercent = addPercent + addNum[2]
                    end
                end
            end
        end

        local id = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
        local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        if id ~= 0 then
            local paramsVo = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(3)
            local cardDojo = cardComponent:GetCardById(tonumber(id))
            if checkNumber(cardDojo.cafeEnergy) >= checkNumber(paramsVo.num) then
                local vo = MaidCoffeeUtils.GetCardManagerInfoVo(cardDojo.cardId)
                ---说明是好评点加成
                if vo.additionId == 5001 then
                    probability = probability + vo.additionNum[1]
                    addPercent = addPercent + vo.additionNum[2]
                end
            end
        end
        local paramsVo = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(4)
        for i = 1, 3 do
            local staffId = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Clerk ,i)
            if staffId ~= 0 then
                local cardDojo = cardComponent:GetCardById(tonumber(staffId))
                if checkNumber(cardDojo.cafeEnergy) >= checkNumber(paramsVo.num) then
                    local vo = MaidCoffeeUtils.GetCardManagerInfoVo(cardDojo.cardId)
                    ---说明是金币加成
                    if vo.additionId == 5001 then
                        probability = probability + vo.additionNum[1]
                        addPercent = addPercent + vo.additionNum[2]
                    end
                end
            end
        end
    end
    return probability,addPercent
end

