---IsHaveNullMenu
---是否有空闲的套餐
function MaidCoffeeComponent:IsHaveNullMenu()
    local isHave = false
    for i = 1, MenuCount do
        local _,isLock = self:GetIsLockedAndVolume(i)
        if not isLock then
            local menuInfo = self:GetCurIndexMenuInfo(i)
            local isSell = menuInfo ~= nil and  menuInfo:IsSell()
            if not isSell then
                isHave = true
                break
            end
        end
    end
    return isHave
end

function MaidCoffeeComponent:RefreshMenuRedPoint()
    local isHaveNullMenu = self:IsHaveNullMenu()
    if not isHaveNullMenu then
        local leftTime = nil
        for i = 1, MenuCount do
            local _,isLock = self:GetIsLockedAndVolume(i)
            if not isLock then
                local menuInfo = self:GetCurIndexMenuInfo(i)
                if menuInfo and menuInfo:IsSell() then
                    if isNull(leftTime) then
                        leftTime = menuInfo:GetRemainTime()
                    else
                        if menuInfo:GetRemainTime() < leftTime then
                           leftTime = menuInfo:GetRemainTime()
                        end
                    end
                end
            end
        end
        ---说明有倒计时红点 如果3个套餐同时正好卖完
        if leftTime > 0 then
            GameUtils.UpdateServerRedPointData({cafeMenuEmpty = leftTime})
        else
            GameUtils.UpdateServerRedPointData({cafeMenuEmpty = 0})
        end
    else
        GameUtils.UpdateServerRedPointData({cafeMenuEmpty = 0})
    end
end

