---是否有空的店长或店员 并且玩家手上其他卡牌有心情值 就是说当空的时候 要有能替换的人
function MaidCoffeeComponent:IsClerkHaveRedPoint()
    local allClerk = self:GetAllClerkIds()
    for i = 1, 3 do
        local isLocked,_ = MaidCoffeeMgr:GetInstance():GetIsLocked(MaidCoffeeConstants.SelectType.Clerk,i)
        if not isLocked then
            local isHave = self:GetClerkRedPointByIndex(i,allClerk)
            if isHave then
                return isHave
            end
        end
    end
    return false
end

function MaidCoffeeComponent:GetClerkRedPointByIndex(index,allClerk)
    local staffId = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Clerk ,index)
    if staffId ~= 0 then
        local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        local cardDojo = cardComponent:GetCardById(tonumber(staffId))
        ---设置心情值和状态 会刷新
        local point = tonumber(cardDojo.cafeEnergy) or 0
        return point == 0
    else
        ---当没有人时  要看其他卡牌是否有心情值
        local isHave = self:JudgeCardHaveEnergy(MaidCoffeeConstants.SelectType.Clerk,allClerk,MaidCoffeeConstants.CafeStatus.InService)
        return isHave
    end
    return false
end
---店长和是否有卡牌心情值为0
function MaidCoffeeComponent:IsManagerHaveRedPoint()
    local id = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
    if id ~= 0 then
        local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        local cardDojo = cardComponent:GetCardById(tonumber(id))
        ---设置心情值和状态 会刷新
        local point = tonumber(cardDojo.cafeEnergy) or 0
        return point == 0
    else
        ---当没有人时  要看其他卡牌是否有心情值
        local isHave = self:JudgeCardHaveEnergy(MaidCoffeeConstants.SelectType.Manager,{},MaidCoffeeConstants.CafeStatus.UnderManagement)
        return isHave
    end
    return false
end

function MaidCoffeeComponent:IsPersonHaveRedPoint()
    local isManagerHave = self:IsManagerHaveRedPoint()
    if isManagerHave then
        return true
    end
    local isClerkHave = self:IsClerkHaveRedPoint()
    if isClerkHave then
        return true
    end
    return false
end

function MaidCoffeeComponent:JudgeCardHaveEnergy(type,IgnoreData,limitType)
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local allCards = cardComponent:GetAllCardTable()
    for k, v in pairs(allCards) do
        local cardVo = MaidCoffeeUtils.GetCardManagerInfoVo(v.cardId)
        if cardVo then
            local jobs = cardVo.job
            for i, j in pairs(jobs) do
                local job = tonumber(j)
                if job == type then
                    local limitStatus2Status = MaidCoffeeUtils.GetMaidCoffeeCardStatusLimit(limitType)
                    local cafeStatus = checkNumber(v.cafeStatus)
                    if not limitStatus2Status[cafeStatus] and not IgnoreData[v.id] then
                        if v.cafeEnergy > 0 then
                            return true
                        end
                    end
                end
            end
        end
    end
    return false
end

function MaidCoffeeComponent:GetLimitType(type)
    if type ==MaidCoffeeConstants.SelectType.Manager  then
        return MaidCoffeeConstants.CafeStatus.UnderManagement
    elseif type ==MaidCoffeeConstants.SelectType.Clerk then
        return MaidCoffeeConstants.CafeStatus.InService
    elseif type ==MaidCoffeeConstants.SelectType.DeliveryMan then
        return MaidCoffeeConstants.CafeStatus.InTakeaway
    else
        printError("---->>>>错误的选择类型 ")
    end
end


