function MaidCoffeeComponent:IsMenuSlotUnLockAndLockLevel(tabIndex,slot)
    local isUnLock = false
    local vo = MaidCoffeeUtils.GetMaidCoffeeMenuVo(tabIndex)
    local lockLevel = vo.placeUnlock[slot]
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local maidCoffeeLevel = component:GetCafeLevel()
    if maidCoffeeLevel >= tonumber(lockLevel) then
        isUnLock = true
    end
    return isUnLock,lockLevel
end

function MaidCoffeeComponent:GetNeedPutOnFoodCount(tabIndex)
    local needFood = 0
    local vo = MaidCoffeeUtils.GetMaidCoffeeMenuVo(tabIndex)
    if not isNull(vo) and not isNull(vo.placeUnlock) then
        local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
        local maidCoffeeLevel = component:GetCafeLevel()
        for i = 1, #vo.placeUnlock do
            if maidCoffeeLevel >= tonumber(vo.placeUnlock[i]) then
                needFood = needFood + 1
            end
        end
    end
    return (needFood ~= 0) and needFood or 1
end

