function MaidCoffeeComponent:GetShowCats()
    local t = {}
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    for i = 1, 6 do
        local staffId = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Cat ,i)
        if tonumber(staffId) ~= 0 then
            local catDojo = eggComponent:GetCat(staffId)
            table.insert(t,catDojo)
        end
    end

    local seqKeys = {}
    if #t > 0 then
        SortByMember(t, "id")
        for i, v in pairs(t) do
            table.insert(seqKeys, string.format('%s%s', tostring(v.id), tostring(v.catId)))
        end
    end
    return t, seqKeys
end

function MaidCoffeeComponent:GetOtherShowCats()
    local t = {}
    for i = 1, 6 do
        local catData = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Cat ,i)
        local catData = checkTable(catData)
        if next(catData) then
            local dojo = CatEggDojo.New()
            dojo:FillData(catData)
            table.insert(t,dojo)
        end
    end

    local seqKeys = {}
    if #t > 0 then
        SortByMember(t, "id")
        for i, v in pairs(t) do
            table.insert(seqKeys, string.format('%s%s', tostring(v.id), tostring(v.catId)))
        end
    end
    return t, seqKeys
end

