function MaidCoffeeComponent:GetRemainPrice(furnitureIds)
    local price = 0
    local oldPrice = 0
    for i, v in pairs(furnitureIds) do
        local isHave = self:IsHaveRenovated(v)
        if not isHave then
            local vo = MaidCoffeeUtils.GetRenovateInfoVo(v)
            if not isNull(vo) then
                price = price + vo.goodsNum
                oldPrice = oldPrice + vo.originalNum
            end
        end
    end
    return price,oldPrice
end

function MaidCoffeeComponent:GetSuitNeedCount(suitId)
    local haveCount = 0
    local needCount = 10
    local suitVo = MaidCoffeeUtils.GetSuitRenovateVo(suitId)
    if not isNull(suitVo) then
        for i, v in pairs(suitVo.furnitureIds) do
            local isHave = self:IsHaveRenovated(v)
            if isHave then
                haveCount = haveCount + 1
            end
        end
        local count  = table.count(suitVo.furnitureIds) - haveCount
        return count
    else
        printError("当前套装Id===== %s 在套装表中不存在",suitId)
    end
    return needCount
end

