---SetMaidCoffeeCatList
---@param selectData TeamCatBallDojo[]
function MaidCoffeeComponent:SetMaidCoffeeCatList(selectData)
    local data = {}
    local isChange = false
    for i = 1, MaidCoffeeConstants.MaidCoffeeCatCount do
        local pos = MaidCoffeeConstants.SelectType.Cat * 100 + i
        local id = self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Cat ,i)
        local playerCatId = 0
        if selectData[i] then
            playerCatId = selectData[i].playerCatId
        end
        if playerCatId ~= id then
            isChange = true
        end
        data[tostring(pos)] = playerCatId
    end

    if isChange then
        local _showCatId = self:GetChangeShowCatId(data)
        GameUtils.Request(Interfaces.MaidCoffeeSetCat, {staffs = table.serialize(data),showCatId = _showCatId}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                for i, v in pairs(data) do
                    self:UpdateStaffInfo(i,tonumber(v))
                end
                self:UpdateShowCatId(_showCatId)
                Events.Broadcast(MaidCoffeeConstants.EventNames.CatManageCatPutOn,{ data = data ,isFirst = response.data.isFirst })
            end
        end)
    end
end

function MaidCoffeeComponent:GetChangeShowCatId(data)
    local showCatId = checkNumber(self:GetShowCatId())
    if showCatId == 0 then
        for i = 1, MaidCoffeeConstants.MaidCoffeeCatCount do
            local pos = MaidCoffeeConstants.SelectType.Cat * 100 + i
            local catId = data[tostring(pos)]
            if catId ~= 0 then
                showCatId = catId
                break
            end
        end
    else
        ---说明有猫球 然后要看一下当前猫球有没有被下掉  如果有 那就要重新设置一下展示猫球
        local showCatIsIn = false
        local id = 0
        for i = 1, MaidCoffeeConstants.MaidCoffeeCatCount do
            local pos = MaidCoffeeConstants.SelectType.Cat * 100 + i
            local catId = data[tostring(pos)]
            if catId ~= 0 and id == 0  then
                id = catId
            end

            if catId == showCatId then
                showCatIsIn = true
            end
        end

        if not showCatIsIn then
            showCatId = id
        end
    end
    return showCatId
end

