function MaidCoffeeComponent:IsHaveCatToPutOn()
    local maxNum = self:GetMaxCountByType(MaidCoffeeConstants.SelectType.Cat)
    for i = 1, maxNum do
        local ownerId =  self:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Cat ,i)
        ---当这个位置没有猫求的时候
        if ownerId == 0 then
            local haveNum = self:GetHaveManageCount()
            local havePutNum = self:GetAllPutOnCatCount()
            ---当拥有的数量 大于已经上阵的数量的时候 说明有猫球可以上阵
            if haveNum > havePutNum then
                return true
            end
        end
    end
    return false
end
