    return  checkTable(CfUtils.Split(str, ","))
end

function MaidCoffeeComponent:RemoveRedPointId(id)
    local ids = self:GetRedPointIds()
    for i = table.count(ids), 1, -1 do
        if checkNumber(id) == checkNumber(ids[i]) then
            table.remove(ids, i)
        end
    end
    self:SaveRedPointData(ids)
end

function MaidCoffeeComponent:AddRedPointId(id)
    local ids = self:GetRedPointIds()
    local isFind = false
    for i, v in pairs(ids) do
        if checkNumber(v) == id then
            isFind = true
        end
    end

    if not isFind then
        table.insert(ids,id)
    end
    self:SaveRedPointData(ids)
end

