    for i, v in pairs(ids) do
        local vo = MaidCoffeeUtils.GetRenovateInfoVo(v)
        if vo.furnitureType == type then
            return true
        end
    end
    return false
end

---Guest  餐厅顾客相关---------------------------------------------------------------------------------------------------------------------
function MaidCoffeeComponent:InitialEventDojo(data)
    if isNull(self.maidCoffeeEventDojo) then
        self.maidCoffeeEventDojo = MaidCoffeeEventDojo.New()
    end
    self.maidCoffeeEventDojo:Fill(data)
end

function MaidCoffeeComponent:GetAllEvents()
    if self.maidCoffeeHomeDojo:IsOther() then
        return self.maidCoffeeHomeDojo:CacheEvents()
    end
    return self.maidCoffeeEventDojo:Events()
end

function MaidCoffeeComponent:FinishEvent(data)
    local eventData = data.eventData
    local detailsData = {}
    local consume = {}
    consume[1] = { goodsId = not isNull(data.subData) and data.subData.goodsId or nil,
                   groupId = not isNull(data.subData) and data.subData.groupId or nil}
    detailsData[1] = {
        id = data.choiceId,
        option = not isNull(data.choice) and  data.choice.choiceIndex or nil,
        consume = consume
    }

    GameUtils.Request(Interfaces.MaidCoffeeCompleteDailyEvent,
            {visitorId = eventData.visitorId,eventId = eventData.eventId,storyId = eventData.storyId,details = table.serialize(detailsData)},
            function(request,response)
                if checkNumber(response.errCode) ~= 0 then
                    Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeFinishEventsError,data)
                    return
                end

                if not isNull(data.subData) then
                    GoodsUtils.ConsumeGoods({{goodsId = data.subData.goodsId, num = data.subData.num}}, false)
                end
           
                self:RemoveEvent(eventData.eventId)
                self:UpdateRefreshSeconds(response.data.refreshSeconds)
                self:UpdateCompleteNum()
                self:UpdateEventRedPoint()

                Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeServerFinishEvents,data)
                local rewards = response.data.rewards
                if #rewards > 0 then
                    GoodsUtils.DrawRewards(rewards)
                    ---关闭当前的页面
                    CS.Engine.UI.UIModule.OpenDialog(
                            {
                                id = Constants.UITypeIds.UICommonRewardPop,
                                parameters = { rewards = rewards,cb = function()
                                    if response.data.unlockEvent > 0 then
                                        self:ShowLockTips(checkNumber(response.data.unlockEvent))
                                    end
                                end }
                            }
                    )
                else
                    if response.data.unlockEvent > 0 then
                        self:ShowLockTips(checkNumber(response.data.unlockEvent))
                    end
                end
            end)
end

function MaidCoffeeComponent:ShowLockTips(unlockEvent)
    local str = localize("解锁了新话题，请到顾客信息中查看")
    if unlockEvent == 2 then
        str = localize("解锁了新话题，请到顾客信息中查看")
    elseif unlockEvent == 3 then
        str = localize("解锁了新的喜好和话题，请到顾客信息中查看")
    end
    GameUtils.Toast(str)
end

function MaidCoffeeComponent:UpdateEventRedPoint()
    local allEvent = self:GetAllEvents()
    if table.count(allEvent) > 0 then
        GameUtils.UpdateServerRedPointData({ cafeVisitorEvent = 0})
    else
        local refreshTime = self:GetRefreshTime()
        if refreshTime > 0  then
            GameUtils.UpdateServerRedPointData({ cafeVisitorEvent = refreshTime})
        else
            GameUtils.UpdateServerRedPointData({ cafeVisitorEvent = -1})
        end
    end
end

function MaidCoffeeComponent:GetRefreshTime()
    return self.maidCoffeeEventDojo:GetRefreshTime()
end

function MaidCoffeeComponent:RemoveEvent(eventId)
    self.maidCoffeeEventDojo:RemoveEvent(eventId)
end

function MaidCoffeeComponent:UpdateRefreshSeconds(time)
    self.maidCoffeeEventDojo:UpdateRefreshSeconds(time)
end

function MaidCoffeeComponent:UpdateCompleteNum()
    self.maidCoffeeHomeDojo:UpdateCompleteNum()
end

------------------------------------------------------

function MaidCoffeeComponent:UpdateVisitPermission(permission)
    self.visitPermission = permission
end

function MaidCoffeeComponent:GetVisitPermission()
    return self.visitPermission or 1
end

function MaidCoffeeComponent:IsLoadOtherHomeSuccess()
    return self.isLoadOtherSuccess
end

function MaidCoffeeComponent:SetIsLoadOtherHomeState(isSuccess)
    self.isLoadOtherSuccess = isSuccess
end

function MaidCoffeeComponent:SaveApplyFriendData(friendId)
    self.applyData[tostring(friendId)] = true
end

function MaidCoffeeComponent:IsHaveApply(friendId)
    if self.applyData[tostring(friendId)] then
        return true
    end
    return false
end

return MaidCoffeeComponent